import pandas as pd

class Solution:
    def rectanglesArea(self, points: pd.DataFrame) -> pd.DataFrame:
        res = []
        pts = points.values.tolist()
        for i in range(len(pts)):
            for j in range(i + 1, len(pts)):
                id1, x1, y1 = pts[i]
                id2, x2, y2 = pts[j]
                if x1 != x2 and y1 != y2:
                    res.append([id1, id2, abs(x1 - x2) * abs(y1 - y2)])
        res.sort(key=lambda r: (-r[2], r[0], r[1]))
        return pd.DataFrame(res, columns=['p1', 'p2', 'area'])

