#include <vector>
#include <string>
#include <algorithm>
using namespace std;

class Solution {
public:
    vector<vector<int>> rectanglesArea(vector<vector<int>>& points) {
        // points rows: {id, x_value, y_value}
        vector<vector<int>> res;
        int n = points.size();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (points[i][1] != points[j][1] && points[i][2] != points[j][2]) {
                    long long area = 1LL * abs(points[i][1] - points[j][1]) *
                                     abs(points[i][2] - points[j][2]);
                    res.push_back({points[i][0], points[j][0], (int)area});
                }
            }
        }
        sort(res.begin(), res.end(), [](const vector<int>& a, const vector<int>& b) {
            if (a[2] != b[2]) return a[2] > b[2];
            if (a[0] != b[0]) return a[0] < b[0];
            return a[1] < b[1];
        });
        return res;
    }
};

