import java.util.*;

class Solution {
    public List<List<Integer>> rectanglesArea(int[][] points) {
        List<List<Integer>> res = new ArrayList<>();
        int n = points.length;
        for (int i = 0; i < n; i++) {
            for (int j = i + ; j < n; j++) {
                if (points[i][1] != points[j][1] && points[i][2] != points[j][2]) {
                    long area = (long) Math.abs(points[i][1] - points[j][1])
                              * Math.abs(points[i][2] - points[j][2]);
                    res.add(Arrays.asList(points[i][0], points[j][0], (int) area));
                }
            }
        }
        res.sort((a, b) -> {
            if (!a.get(2).equals(b.get(2))) return b.get(2) - a.get(2);
            if (!a.get(0).equals(b.get(0))) return a.get(0) - b.get(0);
            return a.get(1) - b.get(1);
        });
        return res;
    }
}

