/**
 * @param {number[][]} points rows: [id, x_value, y_value]
 * @return {number[][]}
 */
var rectanglesArea = function(points) {
    const res = [];
    for (let i = 0; i < points.length; i++) {
        for (let j = i + 1; j < points.length; j++) {
            if (points[i][1] !== points[j][1] && points[i][2] !== points[j][2]) {
                res.push([points[i][0], points[j][0],
                    Math.abs(points[i][1] - points[j][1]) * Math.abs(points[i][2] - points[j][2])]);
            }
        }
    }
    res.sort((a, b) => b[2] - a[2] || a[0] - b[0] || a[1] - b[1]);
    return res;
};

